  $('open-civ-editor').onclick=()=>openEditor();$('close-civ-editor').onclick=closeEditor;
  $('civ-tool').onchange=e=>{brushTool=e.target.value;if(brushTool==='province'){renderer.overlays.provinces=true;$('overlay-provinces').checked=true;}updateTargets();toolHelp();};
  function toolHelp(){const help={ownership:'Paint land to transfer it. Hold Space to pan; Shift-click to pick a country.',culture:'Paint a cultural homeland, independent of political borders.',province:'Paint within the selected province’s nation. Other national territory is protected. Shift-click picks a province.',region:'Click land to transfer its entire connected territory component to the target country.',rectangle:'Drag a rectangle to transfer all selected land to the target country.',pick:'Click any country to select it as the painting target.',addCity:'Click suitable land to found a settlement using its local culture.',moveCity:'Select a settlement in the inspector first, then click its new land location.',createNation:'Click inhabited land to establish a new independent country. Paint to expand it.'};$('civ-edit-help').textContent=help[brushTool]||'';$('civ-paint-target').hidden=['addCity','moveCity','createNation'].includes(brushTool);}
  $('civ-brush-size').oninput=()=>{$('civ-brush-output').value=$('civ-brush-size').value;};
  function at(e){const w=getWorld(),r=$('map').getBoundingClientRect(),p=renderer.camera.toWorld(e.clientX-r.left,e.clientY-r.top);if(!w||p.y<0||p.y>=w.height)return null;const x=((p.x%w.width)+w.width)%w.width,y=p.y;return {x,y,unwrappedX:p.x,index:Math.floor(y)*w.width+Math.floor(x)};}
