  function paintDisk(p){const w=getWorld(),key=brushTool==='culture'?'culture':brushTool==='province'?'province':'ownership',target=+$('civ-paint-target').value,r=+$('civ-brush-size').value;if(!target)return;const parent=key==='province'?find('provinces',target)?.nation:null;for(let y=Math.max(0,Math.floor(p.y-r));y<=Math.min(w.height-1,Math.ceil(p.y+r));y++)for(let xx=Math.floor(p.x-r);xx<=Math.ceil(p.x+r);xx++){if((xx+.5-p.x)**2+(y+.5-p.y)**2>r*r)continue;const x=(xx%w.width+w.width)%w.width,i=y*w.width+x;if(w.layers.elevation[i]<=0||key==='province'&&w.layers.ownership[i]!==parent)continue;write(key,i,target);if(key==='culture'){write('cultureMinority',i,0);write('minorityShare',i,0);}}}
