  function land(i){const w=getWorld();return w.layers.elevation[i]>0&&!w.layers.lake?.[i];}
  const canvas=$('map');
  canvas.addEventListener('pointerdown',e=>{
    if(readOnly||brushTool==='inspect'||space||e.button!==0||worker||isBusy())return;const p=at(e);if(!p)return;e.stopImmediatePropagation();e.preventDefault();canvas.setPointerCapture(e.pointerId);canvas.focus({preventScroll:true});
    if(e.shiftKey||brushTool==='pick'){const kind=brushTool==='culture'?'culture':brushTool==='province'?'province':'nation',key=kind==='nation'?'ownership':kind,id=getWorld().layers[key]?.[p.index];if(id){focusEntity(kind,id);updateTargets();$('civ-paint-target').value=id;}return;}
    if(['ownership','culture','province','region','rectangle'].includes(brushTool)){painting={id:e.pointerId,start:p,last:null,changes:new Map(),before:structuredClone(meta()),derived:Object.fromEntries(derivedLayers().map(k=>[k,getWorld().layers[k].slice()]))};
      if(['ownership','culture','province'].includes(brushTool))stroke(p);
      else if(brushTool==='region'){const w=getWorld(),owner=w.layers.ownership[p.index],target=+$('civ-paint-target').value;if(owner!==target&&land(p.index)){const queue=[p.index],seen=new Set([p.index]);for(let q=0;q<queue.length;q++){const i=queue[q],x=i%w.width,y=Math.floor(i/w.width);write('ownership',i,target);for(const j of [y*w.width+(x+1)%w.width,y*w.width+(x+w.width-1)%w.width,...(y>0?[i-w.width]:[]),...(y<w.height-1?[i+w.width]:[])])if(!seen.has(j)&&w.layers.ownership[j]===owner&&land(j)){seen.add(j);queue.push(j);}}meta().revision++;renderer.invalidateCivilization();}}
    }else if(brushTool==='addCity'){if(!land(p.index)||!getWorld().layers.ownership[p.index])return showToast('Choose claimed land outside a lake.',true);if(getWorld().layers.habitability[p.index]<.015)return showToast('This location cannot support a settlement.',true);if(meta().cities.some(a=>a.cell===p.index))return showToast('There is already a settlement in this cell.',true);
      mutate(()=>{const id=Math.max(0,...meta().cities.map(c=>c.id))+1,cu=culture(getWorld().layers.culture[p.index]);const population=Math.min(20000,Math.max(250,Math.round(getWorld().layers.population[p.index]*.2)));getWorld().layers.population[p.index]=Math.max(population,getWorld().layers.population[p.index]);meta().cities.push({id,name:generateCityName(getWorld(),cu?.id||1,`manual:${id}`),cell:p.index,x:Math.floor(p.x)+.5,y:Math.floor(p.y)+.5,nation:getWorld().layers.ownership[p.index],culture:cu?.id||1,population,capital:false,manual:{position:true}});entityId=id;view='city';},['population']);focusEntity('city',entityId);
    }else if(brushTool==='moveCity'){const a=city(moveCity);if(!a)return showToast('Inspect a city before choosing Move.',true);if(!land(p.index)||meta().cities.some(c=>c.id!==a.id&&c.cell===p.index))return showToast('Choose an empty land cell.',true);mutate(()=>moveSettlement(getWorld(),a.id,p.index),['population']);
    }else if(brushTool==='createNation'){if(!land(p.index))return showToast('Choose land for the new country.',true);let newId;mutate(()=>{const result=createNation(getWorld(),p.index);newId=result?.id||meta().nations.at(-1).id;},['ownership']);if(newId){openEditor('ownership',newId);focusEntity('nation',newId);}}
  },true);
  canvas.addEventListener('pointermove',e=>{if(brushTool==='inspect'||space||worker||isBusy())return;const p=at(e);if(!p)return;e.stopImmediatePropagation();renderer.brush=['ownership','culture','province'].includes(brushTool)?{x:p.unwrappedX,y:p.y,radius:+$('civ-brush-size').value}:null;if(painting&&['ownership','culture','province'].includes(brushTool))stroke(p);if(painting&&brushTool==='rectangle'){painting.end=p;const a=renderer.camera.toScreen(painting.start.unwrappedX,painting.start.y),b=renderer.camera.toScreen(p.unwrappedX,p.y),selection=$('civ-selection');selection.hidden=false;Object.assign(selection.style,{left:Math.min(a.x,b.x)+'px',top:Math.min(a.y,b.y)+'px',width:Math.abs(a.x-b.x)+'px',height:Math.abs(a.y-b.y)+'px'});}renderer.draw();},true);
  function finish(e,cancelled=false){if(!painting)return;e.stopImmediatePropagation();const w=getWorld();if(!cancelled&&brushTool==='rectangle'){const end=at(e)||painting.end||painting.start,start=painting.start,target=+$('civ-paint-target').value,x0=Math.floor(Math.min(start.unwrappedX,end.unwrappedX)),x1=Math.floor(Math.max(start.unwrappedX,end.unwrappedX)),y0=Math.floor(Math.min(start.y,end.y)),y1=Math.floor(Math.max(start.y,end.y));for(let y=y0;y<=y1;y++)for(let x=x0;x<=Math.min(x1,x0+w.width-1);x++){const i=y*w.width+(x%w.width+w.width)%w.width;if(w.layers.elevation[i]>0)write('ownership',i,target);}}
    const changes=[...painting.changes.values()];if(cancelled){for(const [key,i,before]of changes)w.layers[key][i]=before;w.meta.civilization=painting.before;}else if(changes.length){if(brushTool==='province'){const target=find('provinces',+$('civ-paint-target').value);if(target)target.manual={...target.manual,territory:true};}recomputeCivilization(w);const captured=new Set();for(const change of changes){change[3]=w.layers[change[0]][change[1]];captured.add(`${change[0]}:${change[1]}`);}for(const [key,before]of Object.entries(painting.derived||{})){const after=w.layers[key];for(let i=0;i<before.length;i++)if(before[i]!==after[i]&&!captured.has(`${key}:${i}`))changes.push([key,i,before[i],after[i]]);}pushHistory({changes,before:painting.before,after:structuredClone(meta())});redo=[];}painting=null;$('civ-selection').hidden=true;refresh();
  }
  canvas.addEventListener('pointerup',e=>finish(e),true);canvas.addEventListener('pointercancel',e=>finish(e,true),true);
  document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;if(e.key==='Escape'){if(worker){e.preventDefault();e.stopImmediatePropagation();cancel();}else{closeEditor();renderer.selectedNation=0;renderer.selectedProvince=0;renderer.provinceBreakdown='none';$('map-mode').onchange();}return;}if(e.target.matches('input,select,textarea'))return;if(e.code==='Space')space=true;if(!$('civ-editor').hidden&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.stopImmediatePropagation();historyAction(e.shiftKey?'redo':'undo');}},true);
  document.addEventListener('keyup',e=>{if(e.code==='Space')space=false;});window.addEventListener('blur',()=>space=false);
  function exportCensus(){const q=s=>`"${String(s??'').replaceAll('"','""')}"`;const lines=[['Country','Official name','Population','Area km2','Density','Government','Leader','Capital','Settlements','Provinces','Annual output WU','Output per capita WU','Technology 0-100','Currency','Currency per WU','Start date'],...meta().nations.map(n=>[n.name,n.officialName,Math.round(n.population),n.area,n.density,n.government,n.leader?.name,city(n.capital)?.name,meta().cities.filter(c=>c.nation===n.id).length,(meta().provinces||[]).filter(p=>p.nation===n.id).length,n.economicOutput||n.gdp,n.gdpPerCapita,Math.round((n.technology||0)*100),n.currency?.code,n.currency?.rate,meta().startDate])];download(new Blob(['\uFEFF'+lines.map(r=>r.map(q).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'world-census.csv');}
  societyUI=initSocietyUI({getWorld,renderer,changed,mutate,focusEntity,openEditor,generate,refresh});
  setForm(meta()?.settings||DEFAULT_CIV_SETTINGS);$('civ-settings').dispatchEvent(new Event('input'));
  initMapProbe({getWorld,renderer,focusEntity});initOverlayDisclosure();
  render();return {onAdopt,inspectCell,rerender:render,get entityView(){return view;},cancel,generate,stage,closeEditor,focusEntity,setReadOnly(value){readOnly=!!value;closeEditor();for(const id of ['civ-entity-dialog','society-entity-dialog'])if($(id)?.open)$(id).close();render();},get readOnly(){return readOnly;},onModeChange(previous,next){societyUI.modeChange(previous,next);},dispose(){worker?.terminate();},get busy(){return !!worker;},setPhysicalBusy(value){physicalBusy=value;lock(value||!!worker);},get editorActive(){return brushTool!=='inspect';}};
